script:
country_event = {
	id = infernals.10
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		OR = {
			is_world_forger_empire = yes
			is_galvanic_empire = yes
			has_origin = origin_red_giant
			has_origin = origin_cosmic_dawn
			has_valid_civic = civic_pyrolatry
		}
	}

	immediate = {
		if = {
			limit = { is_world_forger_empire = yes }
			add_research_option = tech_volcanic_forge
			# Some origins alter nearby planets
			if = {
				limit = {
					NOR = {
						has_origin = origin_doomsday
						has_origin = origin_shattered_ring
						has_origin = origin_necrophage
						has_origin = origin_void_dwellers
						has_origin = origin_common_ground
						has_origin = origin_hegemon
						has_origin = origin_life_seeded
					}
				}
				capital_scope = { # Guaranteed dry worlds
					closest_system = {
						min_steps = 1
						max_steps = 3
						limit = { has_star_flag = neighbor_t1_first_colony }
						random_system_planet = {
							limit = { has_carrier_flag = prescripted_ideal }
							change_pc = pc_arid
							reroll_planet = yes
							clear_blockers = yes
						}
					}
					closest_system = {
						min_steps = 1
						max_steps = 3
						limit = { has_star_flag = neighbor_t2_second_colony }
						random_system_planet = {
							limit = { has_carrier_flag = prescripted_ideal }
							change_pc = pc_desert
							reroll_planet = yes
							clear_blockers = yes
						}
					}
				}
			}
		}
		if = {
			limit = {
				is_world_forger_empire = yes
				has_origin = origin_necrophage
			}
			capital_scope = { # Necrophage: fix volcanic pre-FTL worlds without rerolling pops
				closest_system = {
					min_steps = 1
					max_steps = 3
					limit = { has_star_flag = neighbor_t1_first_colony }
					random_system_planet = {
						limit = {
							has_carrier_flag = prescripted_ideal
							is_planet_class = pc_volcanic
						}
						change_pc = pc_arid
					}
				}
				closest_system = {
					min_steps = 1
					max_steps = 3
					limit = { has_star_flag = neighbor_t2_second_colony }
					random_system_planet = {
						limit = {
							has_carrier_flag = prescripted_ideal
							is_planet_class = pc_volcanic
						}
						change_pc = pc_desert
					}
				}
			}
		}
		if = {
			limit = { is_galvanic_empire = yes }
			give_technology = {
				tech = tech_mine_living_metal
				message = no
			}
			capital_scope = {
				add_deposit = d_galvanic_living_metal
			}
		}
		if = {
			limit = { has_valid_civic = civic_pyrolatry }
			give_technology = {
				tech = tech_volcano
				message = no
			}
		}
		if = {
			limit = { has_origin = origin_red_giant }
			capital_star = {
				set_deposit = d_red_giant_unstable
				set_planet_entity = { entity = red_giant_tunnel_faint_class_star_entity }
				solar_system = {
					random_system_planet = {
						limit = { has_carrier_flag = red_giant_innerplanet }
						add_deposit = d_minerals_10
					}
					random_system_planet = {
						limit = { has_carrier_flag = red_giant_second_innerplanet }
						add_deposit = d_alloys_5
					}
				}
			}
			country_event = { id = infernals.45 days = 45 }
			capital_scope = {
				save_global_event_target_as = red_giant_homeworld@owner
			}
		}
		if = {
			limit = { has_origin = origin_cosmic_dawn }
			country_event = { id = infernals.2500 days = 1 }
			capital_scope = {
				set_carrier_flag = cosmic_dawn_homeworld
			}
		}
	}
}

